(function(){
  var app=document.getElementById('app'),root=document.documentElement;
  // ----- intro video from embedded data -----
  var vid=document.getElementById('vid');
  vid.src='assets/intro.mp4';
  var pp=vid.play(); if(pp&&pp.catch) pp.catch(function(){});

  // ===================== JAZZ HIP-HOP (synthesized, original) =====================
  // 88 BPM boom-bap with swing, Rhodes-style 9th chords, bass, vinyl crackle. Intro is muffled; drums drop on bar 2.
  var ctx=null,master=null,keysF=null,nextT=0,step=0,bar=0,timer=null,on=true,noiseBuf=null;
  var BPM=88,SD=60/BPM/4,SWING=.34;
  function initAudio(){
    var AC=window.AudioContext||window.webkitAudioContext; if(!AC)return false;
    ctx=new AC(); master=ctx.createGain(); master.gain.value=.9;
    var comp=ctx.createDynamicsCompressor(); comp.threshold.value=-16; comp.ratio.value=3;
    var warm=ctx.createBiquadFilter(); warm.type='lowpass'; warm.frequency.value=7000;
    master.connect(warm); warm.connect(comp); comp.connect(ctx.destination);
    keysF=ctx.createBiquadFilter(); keysF.type='lowpass'; keysF.frequency.value=520; keysF.Q.value=.5; keysF.connect(master);
    noiseBuf=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate); var nd=noiseBuf.getChannelData(0); for(var i=0;i<nd.length;i++)nd[i]=Math.random()*2-1;
    var cb=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate),cd=cb.getChannelData(0);
    for(var j=0;j<cd.length;j++){cd[j]=(Math.random()*2-1)*.012; if(Math.random()<.0009)cd[j]+=(Math.random()<.5?-1:1)*(.25+Math.random()*.5);}
    var cr=ctx.createBufferSource(); cr.buffer=cb; cr.loop=true; var cf=ctx.createBiquadFilter(); cf.type='bandpass'; cf.frequency.value=2500; cf.Q.value=.6;
    var cg=ctx.createGain(); cg.gain.value=.55; cr.connect(cf); cf.connect(cg); cg.connect(master); cr.start();
    return true;
  }
  function noise(){var s=ctx.createBufferSource();s.buffer=noiseBuf;return s;}
  function kick(t,v){
    var o=ctx.createOscillator(),g=ctx.createGain(); o.type='sine';
    o.frequency.setValueAtTime(120,t); o.frequency.exponentialRampToValueAtTime(48,t+.09);
    g.gain.setValueAtTime(v||.95,t); g.gain.exponentialRampToValueAtTime(.001,t+.32);
    o.connect(g); g.connect(master); o.start(t); o.stop(t+.35); pulse(t,1);
  }
  function snare(t,v){
    v=v||.5;
    var s=noise(),bp=ctx.createBiquadFilter(),g=ctx.createGain(); bp.type='bandpass'; bp.frequency.value=1900; bp.Q.value=.7;
    g.gain.setValueAtTime(v,t); g.gain.exponentialRampToValueAtTime(.001,t+.2);
    s.connect(bp); bp.connect(g); g.connect(master); s.start(t); s.stop(t+.22);
    var o=ctx.createOscillator(),og=ctx.createGain(); o.type='triangle'; o.frequency.setValueAtTime(210,t); o.frequency.exponentialRampToValueAtTime(160,t+.06);
    og.gain.setValueAtTime(v*.6,t); og.gain.exponentialRampToValueAtTime(.001,t+.1); o.connect(og); og.connect(master); o.start(t); o.stop(t+.12);
    pulse(t,.55);
  }
  function hat(t,v){
    var s=noise(),hp=ctx.createBiquadFilter(),g=ctx.createGain(); hp.type='highpass'; hp.frequency.value=8000;
    g.gain.setValueAtTime(v||.12,t); g.gain.exponentialRampToValueAtTime(.001,t+.05);
    s.connect(hp); hp.connect(g); g.connect(master); s.start(t); s.stop(t+.06);
  }
  function rhodes(t,f,dur,v){
    var g=ctx.createGain(),o1=ctx.createOscillator(),o2=ctx.createOscillator(),g2=ctx.createGain();
    o1.type='sine'; o1.frequency.value=f; o2.type='sine'; o2.frequency.value=f*2.002; g2.gain.value=.22;
    var lfo=ctx.createOscillator(),lg=ctx.createGain(); lfo.frequency.value=4.6; lg.gain.value=v*.18;
    lfo.connect(lg); lg.connect(g.gain);
    g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(v,t+.012); g.gain.exponentialRampToValueAtTime(v*.35,t+.5); g.gain.exponentialRampToValueAtTime(.001,t+dur);
    o1.connect(g); o2.connect(g2); g2.connect(g); g.connect(keysF);
    [o1,o2,lfo].forEach(function(o){o.start(t);o.stop(t+dur+.05);});
  }
  function chord(t,notes,dur){notes.forEach(function(f,i){rhodes(t+i*.012,f,dur,.06);});}
  function bass(t,f,dur){
    var o=ctx.createOscillator(),g=ctx.createGain(),lp=ctx.createBiquadFilter(); o.type='triangle'; o.frequency.value=f; lp.type='lowpass'; lp.frequency.value=420;
    g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(.42,t+.015); g.gain.exponentialRampToValueAtTime(.001,t+dur);
    o.connect(lp); lp.connect(g); g.connect(master); o.start(t); o.stop(t+dur+.05);
  }
  function b808(t){kick(t,1);}
  function clap(t){snare(t,.45);}
  function hz(m){return 440*Math.pow(2,(m-69)/12);}
  // Dm9 – G13 – Cmaj9 – A7(b13)
  var CH=[[50,53,57,60,64],[53,59,64,69],[48,52,55,59,62],[55,61,65,67]].map(function(c){return c.map(hz)});
  var ROOT=[38,43,36,33], BL=[[0,0,6],[7,7,3],[10,12,3]];
  function schedule(t,s){
    var inBar=s%16, ci=bar%4, tt=t+((inBar%2)?SD*SWING:0);
    if(inBar===0) chord(tt,CH[ci],SD*9);
    if(inBar===10) chord(tt,CH[ci].slice(1),SD*5);
    if(bar===0){ if(inBar%4===2) hat(tt,.05); return; }
    if(bar===1&&inBar===0){ keysF.frequency.setTargetAtTime(2600,t,.05); dropAt(t); }
    BL.forEach(function(b){ if(b[0]===inBar) bass(tt,hz(ROOT[ci]+b[1]),SD*b[2]); });
    if(inBar===0||inBar===7||inBar===10) kick(tt,inBar===0?1:.8);
    if(inBar===4||inBar===12) snare(tt);
    if(inBar%2===0) hat(tt,inBar%4===0?.13:.09); else if(inBar===15) hat(tt,.07);
  }
  function loop(){
    while(nextT<ctx.currentTime+.15){schedule(nextT,step);nextT+=SD;step++;if(step%16===0)bar++;}
  }
  function startBeat(){
    if(!ctx&&!initAudio())return false;
    if(ctx.resume)ctx.resume();
    step=8;bar=0;nextT=ctx.currentTime+.05; clearInterval(timer); timer=setInterval(loop,25); loop();
    return true;
  }
  function pulse(t,amt){
    var ms=Math.max(0,(t-ctx.currentTime)*1000);
    setTimeout(function(){root.style.setProperty('--kick',amt);setTimeout(function(){root.style.setProperty('--kick',0)},130);},ms);
  }
  function dropAt(t){var ms=Math.max(0,(t-ctx.currentTime)*1000);setTimeout(doDrop,ms);}
  function setSound(v){
    on=v; document.querySelectorAll('.snd').forEach(function(b){b.classList.toggle('on',v); b.querySelector('span').textContent=v?'ON':'OFF'; b.setAttribute('aria-label',v?'关闭声音':'打开声音');});
    if(ctx){ if(v){ctx.resume();} else {ctx.suspend();} }
  }
  document.querySelectorAll('.snd').forEach(function(b){b.addEventListener('click',function(){
    if(!ctx){ if(startBeat()){bar=2;keysF.frequency.value=2600;} setSound(true); return; }
    setSound(!on);
  });});
  // ===================== SCREENS =====================
  var intro=document.getElementById('intro'),drop=document.getElementById('drop'),flow=document.getElementById('flow'),look=document.getElementById('look');
  var dropped=false;
  function doDrop(){
    if(dropped)return; dropped=true;
    intro.hidden=true; drop.hidden=false; drop.classList.add('on');
    var f=document.createElement('div'); f.className='flashwhite'; app.appendChild(f); setTimeout(function(){f.remove()},600);
    app.classList.remove('shake'); void app.offsetWidth; app.classList.add('shake');
    setTimeout(function(){drop.classList.add('out'); look.hidden=false; goLook(0); setTimeout(function(){hint.classList.add('gone')},4500); setTimeout(function(){drop.hidden=true;drop.classList.remove('out');},500);},2050);
  }
  document.getElementById('start').addEventListener('click',function(){
    var ok=startBeat();
    if(!ok){ setSound(false); doDrop(); return; }
    // build-up bar plays on the intro screen, then the drop lands on the beat
    this.querySelector('span').textContent='放点音乐 …'; this.disabled=true;
  });

  // ===================== STORY: SUPPLY CHAIN → LOOKBOOK =====================
  var PAGES=[
    {t:'cover',ch:'供应链',img:'data:image/jpeg;base64,',en:'MADE IN GUANGZHOU',cn:'广州番禺 · 长期合作工厂',d:'成衣 + 印花一站式。设计、成衣、印花、生产、发货，一条线做完。'},
    {t:'grid',ch:'供应链',en:'FROM DESIGN TO DELIVERY',cn:'一件衣服怎么来',d:'合作工厂车间实拍，没有 AI。',
      g:[['data:image/jpeg;base64,','01','设计打样'],['data:image/jpeg;base64,','02','热转印'],['data:image/jpeg;base64,','03','印花生产'],['data:image/jpeg;base64,','04','成衣压烫'],['data:image/jpeg;base64,','05','分拣质检'],['data:image/jpeg;base64,','06','打包发货']]},
    {t:'founder',ch:'供应链',img:'data:image/jpeg;base64,',en:'SKIP — 定制主理人',cn:'主理人全程跟单',d:'工厂负责生产，SKIP 盯图案、面料、印花效果、尺码分拣，一直跟到发货。',chips:['DTF 烫画','DTG 数码直喷','按图案推荐工艺']},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'104 LOGO SWEATSHIRT — HEATHER GREY',cn:'圆领卫衣 · 胸前大标',d:'Oversized 版型，正面印花。',p:68},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'104 LOGO HOODIE — BLACK',cn:'连帽卫衣 · 胸前小标',d:'最好搭的一件，小标低调。',p:79},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'104 GRAPHIC L/S TEE — CREAM',cn:'长袖 T 恤 · 袖子印花',d:'正面加袖子两处印花。',p:48},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'104 LOGO HOODIE — SAGE GREEN',cn:'连帽卫衣 · 后背大图',d:'后背整幅印花，舞台上最显眼。',p:79},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'104 WASHED CREWNECK — DUSTY PINK',cn:'圆领卫衣 · 水洗色',d:'水洗做旧的颜色，适合女生团。',p:68},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'L/S TEE — PINK / WHITE / BROWN',cn:'长袖 T 恤 · 一款三色',d:'同一个图，换颜色就是一个系列。',p:48},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'HOODIE — BLACK / GREY / NAVY',cn:'连帽卫衣 · 前后都能印',d:'后背大图、胸前小标，按你的图来。',p:79},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'QUICK-DRY JERSEY — FRONT / BACK',cn:'速干长袖 · 整件满版图案',d:'速干面料，前后整版设计，适合球队、车队、舞团比赛服。',p:0},
    {t:'look',ch:'LOOKBOOK',img:'data:image/jpeg;base64,',en:'GRAPHIC PRINTS',cn:'印花参考 · 图案你来定',d:'满印、做旧、照片级图案都能做。',p:-1},
    {t:'end',ch:'下一步'}
  ];
  var track=document.getElementById('lkTrack'),segs=document.getElementById('segs'),lkNo=document.getElementById('lkNo'),lkTotal=PAGES.length,li=0;
  var chCount={},chIdx=[];
  PAGES.forEach(function(P){chCount[P.ch]=(chCount[P.ch]||0)+1;chIdx.push(chCount[P.ch]);});
  function z(n){return (n<10?'0':'')+n}
  function price(p){return p>0?'¥'+p+'<small>每件起 · 20 件起订</small>':(p===0?'<small>按款报价</small>':'<small>按图案报价</small>');}
  var lh='';
  PAGES.forEach(function(P,i){
    var chap='<span class="box chap">'+P.ch+'</span>';
    if(P.t==='cover'){
      lh+='<article class="lk cover"><div class="ph"><img src="'+P.img+'" alt="合作工厂车间实拍">'+chap+'<div class="over"><p class="code" style="color:#ddd">CHAPTER 01 · 成衣供应链</p><h3 class="disp">Made in<br>Guangzhou</h3><p>'+P.cn+'</p></div></div>'+
          '<div class="cap"><span class="en">'+P.en+' · 实拍</span><b>成衣供应链</b><span class="pr"></span><span class="d">'+P.d+'</span></div></article>';
    }else if(P.t==='grid'){
      var g='';P.g.forEach(function(x){g+='<figure><img src="'+x[0]+'" alt="'+x[2]+'实拍"><figcaption><b>'+x[1]+'</b>'+x[2]+'</figcaption></figure>';});
      lh+='<article class="lk grid"><div class="pg">'+g+'</div>'+
          '<div class="cap"><span class="en">'+P.en+'</span><b>'+P.cn+'</b><span class="pr"></span><span class="d">'+P.d+'</span></div></article>';
    }else if(P.t==='founder'){
      var c='';P.chips.forEach(function(x){c+='<span>'+x+'</span>';});
      lh+='<article class="lk founder"><div class="ph"><img src="'+P.img+'" alt="主理人 SKIP">'+chap+'</div>'+
          '<div class="cap"><span class="en">'+P.en+'</span><b>'+P.cn+'</b><span class="pr"></span><span class="d">'+P.d+'</span><div class="chips2">'+c+'</div></div></article>';
    }else if(P.t==='look'){
      lh+='<article class="lk"><div class="ph"><img src="'+P.img+'" alt="'+P.cn+'">'+chap+'<span class="num">'+z(chIdx[i])+'</span></div>'+
          '<div class="cap"><span class="en">'+P.en+'</span><b>'+P.cn+'</b><span class="pr">'+price(P.p)+'</span><span class="d">'+P.d+'</span></div></article>';
    }else{
      lh+='<article class="lk end"><div class="code" style="margin-bottom:10px">看完了 · NEXT</div><p class="bigq">看中了？<br>换上<em>你的图</em>，<br>就是你的牌子。</p>'+
          '<div class="facts"><div><strong>20</strong>件起订</div><div><strong>¥48</strong>长袖起</div><div><strong>¥68</strong>卫衣起</div></div>'+
          '<button class="go" type="button" id="toFlow"><span>开始选款下单</span><small>5 STEPS →</small></button>'+
          '<p class="hint">选用途、款式、颜色、图案、数量，1 分钟填完</p></article>';
    }
  });
  track.innerHTML=lh;
  var sh='';PAGES.forEach(function(P,k){sh+='<i'+(k>0&&P.ch!==PAGES[k-1].ch?' class="ch"':'')+'></i>';});segs.innerHTML=sh;
  var segEls=[].slice.call(segs.children),cards=[].slice.call(track.children),skipB=document.getElementById('skipLook');
  var arrL=document.getElementById('arrL'),arrR=document.getElementById('arrR'),hint=document.getElementById('swipeHint');
  function mark(i){
    li=i; var P=PAGES[i];
    lkNo.textContent=P.ch+' '+z(chIdx[i])+' / '+z(chCount[P.ch]);
    segEls.forEach(function(e,k){var ch=(k>0&&PAGES[k].ch!==PAGES[k-1].ch)?'ch ':'';e.className=ch+(k<i?'done':(k===i?'cur':''));});
    cards.forEach(function(c,k){c.classList.toggle('active',k===i)});
    arrL.disabled=i===0; arrR.disabled=i===lkTotal-1;
    skipB.textContent=i===lkTotal-1?'开始选款 →':'看完了，直接选款';
    if(i>0)hint.classList.add('gone');
  }
  function leftOf(i){var c=cards[i];return c.offsetLeft-(track.clientWidth-c.clientWidth)/2;}
  function goLook(i){i=Math.max(0,Math.min(lkTotal-1,i)); track.scrollTo({left:leftOf(i),behavior:'smooth'}); mark(i); if(ctx&&on)hat(ctx.currentTime+.005,.18);}
  var lst;track.addEventListener('scroll',function(){
    hint.classList.add('gone');
    clearTimeout(lst);lst=setTimeout(function(){
      var mid=track.scrollLeft+track.clientWidth/2,best=0,bd=1e9;
      cards.forEach(function(c,k){var d=Math.abs(c.offsetLeft+c.clientWidth/2-mid);if(d<bd){bd=d;best=k;}});
      if(best!==li){mark(best); if(ctx&&on)hat(ctx.currentTime+.005,.18);}
    },70);
  });
  arrL.addEventListener('click',function(){goLook(li-1)});
  arrR.addEventListener('click',function(){goLook(li+1)});
  track.addEventListener('click',function(e){var c=e.target.closest('.lk');if(!c||e.target.closest('button'))return;var k=cards.indexOf(c);if(k!==li)goLook(k);});
  function toFlow(){look.classList.add('out');flow.hidden=false;show(1);if(ctx&&on)clap(ctx.currentTime+.01);setTimeout(function(){look.hidden=true;look.classList.remove('out');},500);}
  document.getElementById('toFlow').addEventListener('click',toFlow);
  skipB.addEventListener('click',toFlow);
  mark(0);

  // ===================== GUIDED STEPS =====================
  var state={use:'',cat:[],color:[],art:'',qty:50,when:'',logo:false};
  var cur=1,total=5;
  var steps=[].slice.call(document.querySelectorAll('.step'));
  var nextB=document.getElementById('next'),backB=document.getElementById('back'),foot=document.getElementById('foot');
  function valid(n){
    if(n===1)return !!state.use; if(n===2)return state.cat.length>0; if(n===3)return state.color.length>0;
    if(n===4)return state.logo||!!state.art; if(n===5)return !!state.when; return true;
  }
  function show(n){
    cur=n;
    steps.forEach(function(s){var on=+s.dataset.step===n; s.hidden=!on; if(on){s.classList.remove('enter');void s.offsetWidth;s.classList.add('enter');s.scrollTop=0;}});
    var done=n>total;
    document.getElementById('stepNo').textContent=done?'DONE':'STEP 0'+n+' / 05';
    document.getElementById('bar').style.width=(done?100:n*20)+'%';
    foot.hidden=done; backB.style.visibility=n===1?'hidden':'visible';
    document.getElementById('nextTxt').textContent=n===total?'生成订货单':'下一步';
    nextB.disabled=!valid(n);
    if(done)buildTicket();
  }
  document.querySelectorAll('[data-key]').forEach(function(g){
    var key=g.dataset.key,single=!!g.dataset.single;
    g.addEventListener('click',function(e){
      var b=e.target.closest('button'); if(!b||!g.contains(b))return;
      var v=b.dataset.v;
      if(single){
        g.querySelectorAll('button').forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false')});
        state[key]=v;
        if(key==='use'){nextB.disabled=false;setTimeout(function(){if(cur===1)show(2)},380);}
      }else{
        var p=b.getAttribute('aria-pressed')==='true'; b.setAttribute('aria-pressed',p?'false':'true');
        var arr=state[key],i=arr.indexOf(v); if(p&&i>-1)arr.splice(i,1); if(!p&&i<0)arr.push(v);
      }
      if(ctx&&on)hat(ctx.currentTime+.005,.3);
      nextB.disabled=!valid(cur);
    });
  });
  nextB.addEventListener('click',function(){ if(valid(cur)){ if(ctx&&on)clap(ctx.currentTime+.01); show(cur+1);} });
  backB.addEventListener('click',function(){ if(cur>1)show(cur-1); });

  // logo try-on
  var print=document.getElementById('print'),pimg=document.getElementById('printImg'),pf=document.getElementById('pflash');
  document.getElementById('file').addEventListener('change',function(e){
    var f=e.target.files&&e.target.files[0]; if(!f)return;
    var rd=new FileReader(); rd.onload=function(){
      pimg.src=rd.result; state.logo=true; state.art='';
      document.querySelectorAll('[data-key="art"] button').forEach(function(x){x.setAttribute('aria-pressed','false')});
      print.classList.remove('go2');pf.classList.remove('go2');void print.offsetWidth;print.classList.add('go2');pf.classList.add('go2');
      if(ctx&&on)b808(ctx.currentTime+.01);
      nextB.disabled=!valid(cur);
    }; rd.readAsDataURL(f);
  });

  // quantity
  var qOut=document.getElementById('qtyOut');
  function setQ(q){state.qty=Math.max(20,Math.min(2000,q)); qOut.innerHTML=state.qty+(state.qty>=500?'+':'')+'<small>件</small>';}
  document.getElementById('minus').addEventListener('click',function(){setQ(state.qty-10)});
  document.getElementById('plus').addEventListener('click',function(){setQ(state.qty+10)});
  document.getElementById('quick').addEventListener('click',function(e){var b=e.target.closest('button');if(b)setQ(+b.dataset.q)});

  // ticket
  var orderText='';
  function buildTicket(){
    var no=String(Math.floor(1000+Math.random()*9000));
    document.getElementById('tkNo').innerHTML='NO. '+no+'<br>2026.10';
    var art=state.logo?'已有 logo（微信里发原图）':state.art;
    var rows=[['用途',state.use],['品类',state.cat.join('、')],['颜色',state.color.join('、')],['图案',art],['数量','约 '+state.qty+(state.qty>=500?'+':'')+' 件'],['交期',state.when]];
    var h='';rows.forEach(function(r){h+='<div><span>'+r[0]+'</span><b>'+r[1]+'</b></div>'});
    document.getElementById('tkRows').innerHTML=h;
    var P={'长袖 T 恤':['长袖',48],'圆领卫衣':['圆领',68],'连帽卫衣':['连帽',79],'速干长袖':['速干长袖',0]};
    var parts=[],plain=[];state.cat.forEach(function(c){var x=P[c];if(!x)return;if(x[1]){parts.push(x[0]+' <strong>¥'+x[1]+'</strong>起');plain.push(x[0]+' ¥'+x[1]+' 起');}else{parts.push(x[0]+' 按款报价');plain.push(x[0]+' 按款报价');}});
    document.getElementById('tkPrice').innerHTML='参考起步价：'+parts.join(' · ')+'<br><span class="code">20 件起订 · 最终按款式、数量、印花和工艺报价</span>';
    orderText='【104 秋冬订货单 NO.'+no+'】\n'+rows.map(function(r){return r[0]+'：'+r[1]}).join('\n')+'\n参考起步价：'+plain.join('，')+'（20 件起订，最终按需求报价）\n—— 来自 104 服装造物所秋冬订货页';
  }
  var toast=document.getElementById('toast'),tt;
  function say(m){toast.textContent=m;toast.hidden=false;clearTimeout(tt);tt=setTimeout(function(){toast.hidden=true},2000);}
  function copy(text,ok,fallbackEl){
    function fb(){ if(fallbackEl){var r=document.createRange();r.selectNodeContents(fallbackEl);var s=getSelection();s.removeAllRanges();s.addRange(r);} say('已选中，长按复制'); }
    try{navigator.clipboard.writeText(text).then(function(){say(ok)},fb);}catch(e){fb();}
  }
  document.getElementById('copyOrder').addEventListener('click',function(){copy(orderText,'订货单已复制，加微信后粘贴',document.getElementById('tkRows'))});
  document.getElementById('copyWx').addEventListener('click',function(){copy('grp104','已复制 grp104，去微信添加',document.getElementById('wxid'))});
  document.getElementById('restart').addEventListener('click',function(){
    state={use:'',cat:[],color:[],art:'',qty:50,when:'',logo:false}; setQ(50);
    document.querySelectorAll('[aria-pressed]').forEach(function(x){x.setAttribute('aria-pressed','false')});
    pimg.src=document.querySelector('[data-step="4"] .print img').getAttribute('data-orig')||pimg.src; show(1);
  });
  pimg.setAttribute('data-orig',pimg.src);
  steps.forEach(function(s){s.hidden=+s.dataset.step!==1});
})();
